  4	// Rustan Leino, June 2012.
  5	// This file verifies an algorithm, due to Boyer and Moore, that finds the majority choice
  6	// among a sequence of votes, see http://www.cs.utexas.edu/~moore/best-ideas/mjrty/.
  7	// Actually, this algorithm is a slight variation on theirs, but the general idea for why
  8	// it is correct is the same.  In the Boyer and Moore algorithm, the loop counter is advanced
  9	// by exactly 1 each iteration, which means that there may or may not be a "current leader".
 10	// In my program below, I had instead written the loop invariant to say there is always a
 11	// "current leader", which requires the loop index sometimes to skip a value.
 12	//
 13	// This file has two versions of the algorithm.  In the first version, the given sequence
 14	// of votes is assumed to have a (strict) majority choice, meaning that strictly more than
 15	// 50% of the votes are for one candidate.  It is convenient to have a name for the majority
 16	// choice, in order to talk about it in specifications.  The easiest way to do this in
 17	// Dafny is probably to introduce a ghost parameter with the given properties.  That's what
 18	// the algorithm does, see parameter K.  The postcondition is thus to output the value of
 19	// K, which is done in the non-ghost out-parameter k.
 20	// The proof of the algorithm requires two lemmas.  These lemmas are proved automatically
 21	// by Dafny's induction tactic.
 22	//
 23	// In the second version of the program, the main method does not assume there is a majority
 24	// choice.  Rather, it eseentially uses the first algorithm and then checks if what it
 25	// returns really is a majority choice.  To do this, the specification of the first algorithm
 26	// needs to be changed slightly to accommodate the possibility that there is no majority
 27	// choice.  That change in specification is also reflected in the loop invariant.  Moreover,
 28	// the algorithm itself now needs to extra 'if' statements to see if the entire sequence
 29	// has been searched through.  (This extra 'if' is essentially already handled by Boyer and
 30	// Moore's algorithm, because it increments the loop index by 1 each iteration and therefore
 31	// already has a special case for the case of running out of sequence elements without a
 32	// current leader.)
 33	// The calling harness, DetermineElection, somewhat existentially comes up with the majority
 34	// choice, if there is such a choice, and then passes in that choice as the ghost parameter K
 35	// to the main algorithm.  Neat, huh?
 36	
 37	// Language comment:
 38	// The "(==)" that sits after some type parameters in this program says that the actual
 39	// type argument must support equality.
 40	
 41	// Advanced remark:
 42	// There is a subtle situation in the verification of DetermineElection.  Suppose the type
 43	// parameter Candidate denotes some type whose instances depend on which object are
 44	// allocated.  For example, if Candidate is some class type, then more candidates can come
 45	// into being by object allocations (using "new").  What does the quantification of
 46	// candidates "c" in the postcondition of DetermineElection now mean--all candidates that
 47	// existed in the pre-state or (the possibly larger set of) all candidates that exist in the
 48	// post-state?  (It means the latter.)  And if there does not exist a candidate in majority
 49	// in the pre-state, could there be a (newly created) candidate in majority in the post-state?
 50	// This will require some proof.  The simplest argument seems to be that even if more candidates
 51	// are created during the course of DetermineElection, such candidates cannot possibly
 52	// be in majority in the sequence "a", since "a" can only contain candidates that were already
 53	// created in the pre-state.  This property is easily specified by adding a postcondition
 54	// to the Count function.  Alternatively, one could have added the antecedent "c in a" or
 55	// "old(allocated(c))" to the "forall c" quantification in the postcondition of DetermineElection.
 56	
 57	// About reading the proofs:
 58	// Dafny proves the FindWinner algorithm from the given loop invariants and the two lemmas
 59	// Lemma_Unique and Lemma_Split.  In showing this proof to some colleagues, they found they
 60	// were not as quick as Dafny in constructing the proof from these ingredients.  For a human
 61	// to understand the situation better, it helps to take smaller (and more) steps in the proof.
 62	// At the end of this file, Nadia Polikarpova has written two versions of FindWinner that does
 63	// that, using Dafny's support for calculational proofs.
 64	
 65	function Count<T(==)>(a: seq<T>, s: int, t: int, x: T): int
 66	  requires 0 <= s <= t <= |a|
 67	{
 68	  if s == t then 0 else
 69	  Count(a, s, t-1, x) + if a[t-1] == x then 1 else 0
 70	}
 71	
 72	ghost predicate HasMajority<T>(a: seq<T>, s: int, t: int, x: T)
 73	  requires 0 <= s <= t <= |a|
 74	{
 75	  2 * Count(a, s, t, x) > t - s
 76	}
 77	
 78	// Here is the first version of the algorithm, the one that assumes there is a majority choice.
 79	
 80	method FindWinner<Candidate(==)>(a: seq<Candidate>, ghost K: Candidate) returns (k: Candidate)
 81	  requires HasMajority(a, 0, |a|, K) // K has a (strict) majority of the votes
 82	  ensures k == K  // find K
 83	{
 84	  k := a[0];
 85	  var n, c, s := 1, 1, 0;
 86	  while n < |a|
 87	    invariant 0 <= s <= n <= (|a|) + 1
 88	    invariant 2 * Count(a, s, |a|, K) > |a| - s  // K has majority among a[s..]
 89	    invariant 2 * Count(a, s, n, k) > n - s  // k has majority among a[s..n]
 90	    invariant c == Count(a, s, n, k)
 91	  {
 92	    if a[n] == k {
 93	      n, c := n + 1, c + 1;
 94	    } else if 2 * c > n + 1 - s {
 95	      n := n + 1;
 96	    } else {
 97	      n := n + 1;
 98	      // We have 2*Count(a, s, n, k) == n-s, and thus the following lemma
 99	      // lets us conclude 2*Count(a, s, n, K) <= n-s.
100	      Lemma_Unique(a, s, n, K, k);
101	      // We also have 2*Count(a, s, |a|, K) > |a|-s, and the following lemma
102	      // tells us Count(a, s, |a|, K) == Count(a, s, n, K) + Count(a, n, |a|, K),
103	      // and thus we can conclude 2*Count(a, n, |a|, K) > |a|-n.
104	      Lemma_Split(a, s, n, |a|, K);
105	      k, n, c, s := a[n], n + 1, 1, n;
106	    }
107	  }
108	  Lemma_Unique(a, s, |a|, K, k);  // both k and K have a majority, so K == k
109	}
110	
111	// ------------------------------------------------------------------------------
112	
113	// Here is the second version of the program, the one that also computes whether or not
114	// there is a majority choice.
115	
116	datatype Result<Candidate> = NoWinner | Winner(cand: Candidate)
117	
118	method DetermineElection<Candidate(==,0,!new)>(a: seq<Candidate>) returns (result: Result<Candidate>)
119	  ensures result.Winner? ==> 2 * Count(a, 0, |a|, result.cand) > |a|
120	  ensures result.NoWinner? ==> forall c :: 2 * Count(a, 0, |a|, c) <= |a|
121	{
122	  if |a| == 0 { return NoWinner; }
123	  ghost var b := exists c :: 2 * Count(a, 0, |a|, c) > |a|;
124	  ghost var w :| b ==> 2 * Count(a, 0, |a|, w) > |a|;
125	  var cand := SearchForWinner(a, b, w);
126	  return if 2 * Count(a, 0, |a|, cand) > |a| then Winner(cand) else NoWinner;
127	}
128	
129	// The difference between SearchForWinner for FindWinner above are the occurrences of the
130	// antecedent "hasWinner ==>" and the two checks for no-more-votes that may result in a "return"
131	// statement.
132	
133	method SearchForWinner<Candidate(==)>(a: seq<Candidate>, ghost hasWinner: bool, ghost K: Candidate) returns (k: Candidate)
134	  requires |a| != 0
135	  requires hasWinner ==> 2 * Count(a, 0, |a|, K) > |a|  // K has a (strict) majority of the votes
136	  ensures hasWinner ==> k == K  // find K
137	{
138	  k := a[0];
139	  var n, c, s := 1, 1, 0;
140	  while n < |a|
141	    invariant 0 <= s <= n <= |a|
142	    invariant hasWinner ==> 2 * Count(a, s, |a|, K) > |a| - s  // K has majority among a[s..]
143	    invariant 2 * Count(a, s, n, k) > n - s  // k has majority among a[s..n]
144	    invariant c == Count(a, s, n, k)
145	  {
146	    if a[n] == k {
147	      n, c := n + 1, c + 1;
148	    } else if 2 * c > n + 1 - s {
149	      n := n + 1;
150	    } else {
151	      n := n + 1;
152	      // We have 2*Count(a, s, n, k) == n-s, and thus the following lemma
153	      // lets us conclude 2*Count(a, s, n, K) <= n-s.
154	      Lemma_Unique(a, s, n, K, k);
155	      // We also have 2*Count(a, s, |a|, K) > |a|-s, and the following lemma
156	      // tells us Count(a, s, |a|, K) == Count(a, s, n, K) + Count(a, n, |a|, K),
157	      // and thus we can conclude 2*Count(a, n, |a|, K) > |a|-n.
158	      Lemma_Split(a, s, n, |a|, K);
159	      if |a| == n { return; }
160	      k, n, c, s := a[n], n + 1, 1, n;
161	    }
162	  }
163	  Lemma_Unique(a, s, |a|, K, k);  // both k and K have a majority, so K == k
164	}
165	
166	// ------------------------------------------------------------------------------
167	
168	// Here are two lemmas about Count that are used in the methods above.
169	
170	lemma Lemma_Split<T>(a: seq<T>, s: int, t: int, u: int, x: T)
171	  requires 0 <= s <= t <= u <= |a|
172	  ensures Count(a, s, t, x) + Count(a, t, u, x) == Count(a, s, u, x)
173	{
174	  /* The postcondition of this method is proved automatically via Dafny's
175	     induction tactic.  But if a manual proof had to be provided, it would
176	     look like this:
177	  if s != t {
178	    Lemma_Split(a, s, t-1, u, x);
179	  }
180	  */
181	}
182	
183	lemma Lemma_Unique<T>(a: seq<T>, s: int, t: int, x: T, y: T)
184	  requires 0 <= s <= t <= |a|
185	  ensures x != y ==> Count(a, s, t, x) + Count(a, s, t, y) <= t - s
186	{
187	  /* The postcondition of this method is proved automatically via Dafny's
188	     induction tactic.  But if a manual proof had to be provided, it would
189	     look like this:
190	  if s != t {
191	    Lemma_Unique(a, s, t-1, x, y);
192	  }
193	  */
194	}
195	
196	// ------------------------------------------------------------------------------
197	
198	// This version uses more calculations with integer formulas
199	method FindWinner'<Candidate(==)>(a: seq<Candidate>, ghost K: Candidate) returns (k: Candidate)
200	  requires HasMajority(a, 0, |a|, K) // K has a (strict) majority of the votes
201	  ensures k == K  // find K
202	{
203	  k := a[0]; // Current candidate: the first element
204	  var lo, up, c := 0, 1, 1; // Window: [0..1], number of occurrences of k in the window: 1
205	  while up < |a|
206	    invariant 0 <= lo < up <= |a| // (0)
207	    invariant HasMajority(a, lo, |a|, K) // (1) K has majority among a[lo..]
208	    invariant HasMajority(a, lo, up, k) // (2) k has majority among a[lo..up] (in the current window)
209	    invariant c == Count(a, lo, up, k) // (3)
210	  {
211	    if a[up] == k {
212	      // One more occurrence of k
213	      up, c := up + 1, c + 1;
214	    } else if 2 * c > up + 1 - lo {
215	      // An occurrence of another value, but k still has the majority
216	      up := up + 1;
217	    } else {
218	      // An occurrence of another value and k just lost the majority.
219	      // Prove that k has exactly 50% in the future window a[lo..up + 1]:
220	      calc /* k has 50% among a[lo..up + 1] */ {
221	        true;
222	      ==  // negation of the previous branch condition;
223	        2 * c <= up + 1 - lo;
224	      ==  // loop invariant (3)
225	        2 * Count(a, lo, up, k) <= up + 1 - lo;
226	      == calc {
227	           true;
228	         ==  // loop invariant (2)
229	           HasMajority(a, lo, up, k);
230	         ==  // def. HasMajority
231	           2 * Count(a, lo, up, k) > up - lo;
232	         ==
233	           2 * Count(a, lo, up, k) >= up + 1 - lo;
234	         }
235	        2 * Count(a, lo, up, k) == up + 1 - lo;
236	      }
237	      up := up + 1;
238	      assert 2 * Count(a, lo, up, k) == up - lo; // k has exactly 50% in the current window a[lo..up]
239	
240	      // We are going to start a new window a[up..up + 1] and choose a new candidate,
241	      // so invariants (2) and (3) will be easy to re-establish.
242	      // To re-establish (1) we have to prove that K has majority among a[up..], as up will become the new lo.
243	      // The main idea is that we had enough K's in a[lo..], and there cannot be too many in a[lo..up].
244	      calc /* K has majority among a[up..] */ {
245	        2 * Count(a, up, |a|, K);
246	      ==  { Lemma_Split(a, lo, up, |a|, K); }
247	        2 * Count(a, lo, |a|, K) - 2 * Count(a, lo, up, K);
248	      >  { assert HasMajority(a, lo, |a|, K); } // loop invariant (1)
249	        |a| - lo - 2 * Count(a, lo, up, K);
250	      >=  { if k == K {
251	              calc {
252	                2 * Count(a, lo, up, K);
253	              ==
254	                2 * Count(a, lo, up, k);
255	              ==  { assert 2 * Count(a, lo, up, k) == up - lo; } // k has 50% among a[lo..up]
256	                up - lo;
257	              }
258	            } else {
259	              calc {
260	                2 * Count(a, lo, up, K);
261	              <=  { Lemma_Unique(a, lo, up, k, K); }
262	                2 * ((up - lo) - Count(a, lo, up, k));
263	              ==  { assert 2 * Count(a, lo, up, k) == up - lo; } // k has 50% among a[lo..up]
264	                up - lo;
265	              }
266	            }
267	            assert 2 * Count(a, lo, up, K) <= up - lo;
268	          }
269	        |a| - lo - (up - lo);
270	      ==
271	        |a| - up;
272	      }
273	      assert HasMajority(a, up, |a|, K);
274	
275	      k, lo, up, c := a[up], up, up + 1, 1;
276	      assert HasMajority(a, lo, |a|, K);
277	    }
278	  }
279	  Lemma_Unique(a, lo, |a|, K, k);  // both k and K have a majority among a[lo..], so K == k
280	}
