291	    invariant HasMajority(a, lo, |a|, K) // (1) K has majority among a[lo..]
292	    invariant HasMajority(a, lo, up, k) // (2) k has majority among a[lo..up] (in the current window)
293	    invariant c == Count(a, lo, up, k) // (3)
294	  {
295	    if a[up] == k {
296	      // One more occurrence of k
297	      up, c := up + 1, c + 1;
298	    } else if 2 * c > up + 1 - lo {
299	      // An occurrence of another value, but k still has the majority
300	      up := up + 1;
301	    } else {
302	      // An occurrence of another value and k just lost the majority.
303	      // Prove that k has exactly 50% in the future window a[lo..up + 1]:
304	      calc /* k has 50% among a[lo..up + 1] */ {
305	        true;
306	      ==  // negation of the previous branch condition
307	        2 * c <= up + 1 - lo;
308	      ==  // loop invariant (3)
309	        2 * Count(a, lo, up, k) <= up + 1 - lo;
310	      ==  calc {
311	            true;
312	          ==  // loop invariant (2)
313	            HasMajority(a, lo, up, k);
314	          ==  // def. HasMajority
315	            2 * Count(a, lo, up, k) > up - lo;
316	          ==
317	            2 * Count(a, lo, up, k) >= up + 1 - lo;
318	          }
319	        2 * Count(a, lo, up, k) == up + 1 - lo;
320	      }
321	      up := up + 1;
322	      assert 2 * Count(a, lo, up, k) == up - lo; // k has exactly 50% in the current window a[lo..up]
323	
324	      // We are going to start a new window a[up..up + 1] and choose a new candidate,
325	      // so invariants (2) and (3) will be easy to re-establish.
326	      // To re-establish (1) we have to prove that K has majority among a[up..], as up will become the new lo.
327	      // The main idea is that we had enough K's in a[lo..], and there cannot be too many in a[lo..up].
328	      calc /* K has majority among a[up..] */ {
329	        true;
330	      ==  // loop invariant (1)
331	        HasMajority(a, lo, |a|, K);
332	      ==
333	        2 * Count(a, lo, |a|, K) > |a| - lo;
334	      ==  { Lemma_Split(a, lo, up, |a|, K); }
335	        2 * Count(a, lo, up, K) + 2 * Count(a, up, |a|, K) > |a| - lo;
336	      ==>
337	        { if k == K {
338	            calc {
339	              2 * Count(a, lo, up, K);
340	            ==
341	              2 * Count(a, lo, up, k);
342	            ==  { assert 2 * Count(a, lo, up, k) == up - lo; } // k has 50% among a[lo..up]
343	              up - lo;
344	            }
345	          } else {
346	            calc {
347	              true;
348	            ==  { Lemma_Unique(a, lo, up, k, K); }
349	              Count(a, lo, up, K) + Count(a, lo, up, k) <= up - lo;
350	            ==
351	              2 * Count(a, lo, up, K) + 2 * Count(a, lo, up, k) <= 2 * (up - lo);
352	            ==  { assert 2 * Count(a, lo, up, k) == up - lo; } // k has 50% among a[lo..up]
353	              2 * Count(a, lo, up, K) <= up - lo;
354	            }
